SELECT c.c_customer_id, hd.hd_buy_potential, sm.sm_ship_mode_id, SUM(cs.cs_ext_sales_price) AS total_sales, SUM(cs.cs_ext_discount_amt) AS total_discount, RANK() OVER (PARTITION BY sm.sm_ship_mode_id ORDER BY SUM(cs.cs_ext_sales_price) DESC) AS sales_rank FROM catalog_sales cs JOIN customer c ON cs.cs_bill_customer_sk = c.c_customer_sk JOIN household_demographics hd ON cs.cs_bill_hdemo_sk = hd.hd_demo_sk JOIN ship_mode sm ON cs.cs_ship_mode_sk = sm.sm_ship_mode_sk WHERE cs.cs_quantity > 10 GROUP BY c.c_customer_id, hd.hd_buy_potential, sm.sm_ship_mode_id HAVING SUM(cs.cs_ext_sales_price) > 50000 ORDER BY total_sales DESC LIMIT 25
